package local.pocketchat;
import android.app.*;import android.content.*;import android.graphics.*;import android.graphics.drawable.GradientDrawable;import android.os.*;import android.view.*;import android.widget.*;import java.io.*;

/** First-run brand screen, then the user's selected default entry. No hidden chat session. */
public class BrandLaunchActivity extends Activity {
  void route(){AppSettings.put(this,"brandSeen","true");if(AppSettings.bool(this,"startupDirect",true)){int id=AppSettings.defaultSlot(this);ProfileCatalog.get(this).opened(id);startActivity(new Intent(this,Profiles.activity(id)).putExtra("openWindowAction","chat").putExtra("forceWebMode",true).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK|Intent.FLAG_ACTIVITY_REORDER_TO_FRONT));}else startActivity(new Intent(this,WindowHomeActivity.class));finish();}
  @Override public void onCreate(Bundle state){super.onCreate(state);DesignUi.chrome(this);if(AppSettings.bool(this,"brandSeen",false)&&!getIntent().getBooleanExtra("previewBrand",false)){route();return;}FrameLayout frame=new FrameLayout(this);frame.setFitsSystemWindows(true);frame.setBackgroundColor(DesignUi.BG);ImageView art=new ImageView(this);art.setScaleType(ImageView.ScaleType.CENTER_CROP);try(InputStream in=getAssets().open("brand-portal.png")){art.setImageBitmap(BitmapFactory.decodeStream(in));}catch(Exception ignored){}frame.addView(art,new FrameLayout.LayoutParams(-1,-1));View shade=new View(this);shade.setBackground(new GradientDrawable(GradientDrawable.Orientation.TOP_BOTTOM,new int[]{0x4404101e,0x0004101e,0xee04101e}));frame.addView(shade,new FrameLayout.LayoutParams(-1,-1));LinearLayout content=DesignUi.column(this);content.setPadding(DesignUi.dp(this,24),DesignUi.dp(this,34),DesignUi.dp(this,24),DesignUi.dp(this,28));content.setGravity(Gravity.CENTER_HORIZONTAL);ImageView logo=DesignUi.icon(this,"brand",DesignUi.CYAN,72);content.addView(logo);TextView name=DesignUi.text(this,"元婴期院士",30,DesignUi.TEXT);name.setGravity(Gravity.CENTER);name.setTypeface(Typeface.create("sans-serif",Typeface.BOLD_ITALIC));name.setShadowLayer(12,0,0,DesignUi.BLUE);name.setPadding(0,DesignUi.dp(this,14),0,DesignUi.dp(this,5));content.addView(name);TextView subtitle=DesignUi.text(this,"Android ChatGPT 网页客户端",13,DesignUi.TEXT);subtitle.setGravity(Gravity.CENTER);content.addView(subtitle);content.addView(new View(this),new LinearLayout.LayoutParams(1,0,1));TextView slogan=DesignUi.text(this,"连接更大的世界",24,DesignUi.TEXT);slogan.setTypeface(Typeface.DEFAULT_BOLD);slogan.setGravity(Gravity.CENTER);content.addView(slogan);TextView detail=DesignUi.text(this,"独立窗口 · 隐私保护\n多网络环境 · 安全 · 可控",14,DesignUi.MUTED);detail.setGravity(Gravity.CENTER);detail.setPadding(0,DesignUi.dp(this,9),0,DesignUi.dp(this,24));content.addView(detail);content.addView(DesignUi.button(this,"立即进入  →",true,()->route()),new LinearLayout.LayoutParams(-1,DesignUi.dp(this,48)));TextView footer=DesignUi.text(this,"默认窗口直达 · 窗口管理 · 下载汇总\n网络中心 · 设置分层\nv1.5.0",11,DesignUi.MUTED);footer.setGravity(Gravity.CENTER);footer.setPadding(0,DesignUi.dp(this,16),0,0);content.addView(footer);frame.addView(content,new FrameLayout.LayoutParams(-1,-1));setContentView(frame);}
}
